pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an arbitrary caller and an arbitrary observed target address
    function testFuzz_property(address caller, address target) public {
        // keep addresses non-zero to be in sensible domain, but otherwise wide
        vm.assume(caller != address(0));
        vm.assume(target != address(0));

        // record balance of target before the NETM call
        uint256 before = c.balanceOf(target);

        // have `caller` invoke NETM(); NETM is non-payable and takes no args
        // Use try/catch to tolerate either success or revert (mutant may allow, ref will revert for non-owner)
        bool ok;
        vm.prank(caller);
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // record balance after
        uint256 after = c.balanceOf(target);

        // General property: For the reference contract, calling NETM() by an arbitrary caller
        // cannot increase the balance of an unrelated target address (only owner may call NETM
        // and in the reference setup owner is the deployer, not `caller`).
        // Thus, for all inputs, reference satisfies: before == after.
        // The mutant that removes onlyOwner can allow a non-owner caller to become owner and
        // receive the assigned tokens, making balances[target] differ for some inputs.
        assertTrue(before == after);
    }
}

