        vm.assume(caller != deployer);

        // Record balance of target before the NETM call
        uint256 before = c.balanceOf(target);

        // Make the fuzzed caller invoke NETM(); in the reference this should revert (onlyOwner) or at least not affect balances[target]
        bool ok;
        vm.prank(caller);
        try c.NETM() {
