// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        // deployer (test contract) is the creator of C via new C()
        c = new C();
        deployer = address(this);
    }

    // fuzz parameter: an arbitrary caller address that will invoke NETM()
    function testFuzz_property(address caller) public {
        // keep caller non-zero (still wide)
        if (caller == address(0)) caller = address(1);

        // record balance of the original deployer (owner at construction)
        uint256 before = c.balanceOf(deployer);

        // Have the fuzzed caller invoke NETM(). If the contract requires onlyOwner, only deployer can call
        // and NETM will simply assign balances[owner] = totalDistributed (idempotent), leaving deployer's balance unchanged.
        // If onlyOwner check is removed, some caller may become owner and cause balances[deployer] to change.
        bool ok;
        // execute NETM as the fuzzed caller
        vm.prank(caller);
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: in the correct contract, regardless of who called NETM (whether it succeeded or reverted),
        // the deployer's balance must remain equal to its pre-call value. The mutant (allowing anyone to become owner)
        // can change deployer's balance for some caller inputs, causing this to fail.
        uint256 after = c.balanceOf(deployer);
        assertTrue(after == before);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        c = new C();
        deployer = address(this); // test contract deployed C, so this is owner
    }

    // fuzzed params: caller who will attempt to call NETM and a target address to observe
    function testFuzz_property(address caller, address target) public {
        // keep addresses non-zero to be meaningful and avoid trivial zero-address issues
        vm.assume(caller != address(0));
        vm.assume(target != address(0));

        // record balance of target before
        uint256 before = c.balanceOf(target);

        // have 'caller' attempt to call NETM()
        // If caller is a contract with no code (EOA), the call will succeed or revert depending on onlyOwner.
        // Use vm.prank to simulate the external caller.
        vm.prank(caller);
        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // record balance after
        uint256 after = c.balanceOf(target);

        // The reference contract ensures that only the original deployer (owner) can successfully invoke NETM()
        // and NETM only assigns balances to owner; therefore, for ANY caller, the balance of an arbitrary
        // target address cannot increase unless target == deployer AND caller was the deployer.
        // We'll assert the following universal property: if the caller is NOT the original deployer,
        // then target's balance must remain unchanged after the call (NETM cannot have given tokens to an unrelated target).
        // This holds for the reference; the mutant that removes onlyOwner allows any caller to become owner
        // and assign tokens, so the fuzzer can find caller/target that make after > before.

        if (caller != deployer) {
            assertTrue(after == before);
        } else {
            // If caller is the deployer, NETM may succeed and assign tokens to the deployer; in that case
            // target's balance should remain unchanged unless target == deployer. So enforce that.
            if (target != deployer) {
                assertTrue(after == before);
            } else {
                // when deployer called and target is deployer, NETM may change deployer's balance; nothing to assert
                assertTrue(true);
            }
        }
    }
}
